from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
assert 'js/breeding.js' not in (ROOT/'index.html').read_text(encoding='utf8'), 'One-time integration already applied; do not rerun.'
def edit(name,a,b):
    p=ROOT/name
    s=p.read_text(encoding='utf8')
    assert a in s,(name,a[:100])
    p.write_text(s.replace(a,b),encoding='utf8')
